#let benchmark_results_table() = {
  let data = bench_data()
  let meta = data.meta
  let dirty_tag = if "dirty" in meta and meta.dirty { [ · árbol modificado] } else { [] }
  let rows = benchmark_rows().map(((label, sub, wl, has_model)) => {
    let sib = bench_find(data, "sibuna", sub, wl)
    let model = none
    (
      [#label],
      [#fmt_ns(if sib != none { sib.ns_per_op_median } else { none })],
      [#fmt_ns(if sib != none { sib.ns_per_op_min } else { none }) – #fmt_ns(if sib != none { sib.ns_per_op_max } else { none })],
      [#fmt_int(if sib != none { sib.ops_per_sec } else { none })],
    )
  }).flatten()
  let naive = bench_find(data, "sibuna-naive", "bot_matcher", "sequential_substring_40_signatures")
  let ac = bench_find(data, "sibuna", "bot_matcher", "aho_corasick_40_signatures")
  [
    #text(size: 8pt, fill: gray)[
      Registrado #meta.date · #meta.host · #meta.cpu · #meta.os · revisión
      #raw(meta.git)#dirty_tag · Zig #meta.zig · ReleaseFast · 7 lotes, mediana e intervalo mín–máx
    ]
    #v(6pt)
    #grid(
      columns: (1fr, 1fr, 1fr, 1fr),
      gutter: 6pt,
      stat_tile([#fmt_ns(bench_find(data, "sibuna", "pow_verify", "hashcash_16_bits").ns_per_op_median)], [Verificación Hashcash],
        [SHA-256 por hardware, sin asignaciones], fill: blue_light, stroke: blue),
      stat_tile([#fmt_ns(bench_find(data, "sibuna", "token_auth", "blake3_mac_token").ns_per_op_median)], [Comprobación del token de sesión],
        [BLAKE3 con clave, cookie de 75 caracteres], fill: green_light, stroke: green),
      stat_tile([#calc.round(meta.idle_rss_kb / 1024, digits: 1) MiB], [Memoria residente en reposo],
        [Daemon tras el inicio, almacenamiento desactivado], fill: amber_light, stroke: amber),
      stat_tile([#calc.round(meta.binary_bytes / 1048576, digits: 1) MiB], [Binario del daemon],
        [Solucionador WASM: #meta.wasm_bytes bytes], fill: rgb("f5f3ff"), stroke: rgb("7c3aed")),
    )
    #v(8pt)
    #block(width: 100%, inset: 10pt, radius: 5pt, fill: blue_light, stroke: 0.5pt + rule)[
      #text(size: 11pt, weight: "bold")[Latencia medida por operación]
      #linebreak()
      #text(size: 8pt, fill: gray)[Se muestran las latencias medidas de las primitivas. No se mide la actividad de asignación de memoria.]
      #v(5pt)
      #table(
        columns: (1.6fr, 0.8fr, 1fr, 0.8fr),
        table.header([*Carga*], [*Mediana*], [*Intervalo*], [*ops/s*]),
        ..rows,
      )
      #v(4pt)
      #text(size: 8pt, fill: gray)[Como referencia, buscar las mismas 40 firmas de bots mediante búsqueda secuencial de subcadenas en este host cuesta #fmt_ns(naive.ns_per_op_median), frente a #fmt_ns(ac.ns_per_op_median) con el autómata.]
    ]
  ]
}

