#let cluster_parity_table() = {
  let data = cluster_data()
  let mark(v) = if v == true { text(fill: green, weight: "bold")[OK] } else if v == false { text(fill: red, weight: "bold")[fallo] } else { [-] }
  let rows = ()
  for c in data.cases.filter(c => c.status == "passed") {
    let ch = c.checks
    let idle = c.idle
    let fail = c.at("failover", default: none)
    rows.push((
      [#c.case],
      [#idle.cpu_cores_per_node.map(v => str(calc.round(v * 100, digits: 1))).join([ #sym.slash ]) %],
      idle.rss_kib_per_node.map(k => fmt_mib(k)).join([ #sym.slash ]),
      mark(ch.cross_node_session), mark(ch.waf_denial_with_session),
      mark(ch.at("solution_replay_rejected_on_other_node", default: none)),
      if "ban_propagation_ms" in ch { [#text(dir: ltr, lang: "en")[#calc.round(ch.ban_propagation_ms, digits: 0) ms]] } else { [-] },
      if fail == none { [-] } else { [nodo #fail.stopped_leader_node detenido: #fmt_int(fail.admitted_all_survivors.requests_per_second_median) req/s, bloqueo #text(dir: ltr, lang: "en")[#calc.round(fail.post_failover_ban_propagation_ms, digits: 0) ms]] },
      mark(ch.storage_chain_log_clean),
    ))
  }
  set text(size: 7.4pt)
  set par(justify: false)
  table(
    columns: (1.1fr, 0.8fr, 0.9fr, 0.55fr, 0.55fr, 0.6fr, 0.6fr, 1.3fr, 0.55fr),
    inset: 4pt, stroke: 0.4pt + rule,
    fill: (col, row) => if row == 0 { blue_light } else { none },
    table.header([*Caso*], [*CPU en reposo por nodo*], [*RSS en reposo por nodo*], [*Sesión en cada nodo*], [*WAF deniega con sesión*], [*Replay re­cha­za­do en otro nodo*], [*Pro­pa­ga­ción de blo­que­os*], [*Líder detenido*], [*Log limpio*]),
    ..rows.flatten(),
  )
}
